    const width = [...text].length * fontSize * 0.66 + 8;
    const height = fontSize * 1.25;
    const left = textAnchor === 'start' ? x : textAnchor === 'end' ? x - width : x - width / 2;
    return { x: left, y: y - height * 0.8, width, height };
};

